    /// OMEGA-DELTA-0137. The basic delegation name keeps the established
    /// session machinery while making executor choice and attribution typed.
    #[test]
    fn delegate_names_never_substitutes_and_discloses_what_ran() {
        let tools = read_repository_file("crates/agent/src/tools.rs");
        assert!(
            tools.contains("SpawnAgentTool::NAME => Some(\"delegate\")"),
            "OMEGA-DELTA-0137: the basic profile no longer exposes delegation \
             under the model-facing `delegate` name."
        );

        let tool = read_repository_file("crates/agent/src/tools/spawn_agent_tool.rs");
        for required in [
            "rename = \"task\", alias = \"message\"",
            "rename = \"session\"",
            "\"required\": [\"executor\", \"task\", \"label\"]",
            "\"final_message\": output",
            "\"disclosure\": executor",
            "\"executor_chain\": executor_chain",
            "\"session_address\": session_address",
            "disclosure_matches_requested_executor",
            "NoExecutor",
            "AccountExhausted",
            "AccountRateLimited",
            "EngineUnavailable",
        ] {
            assert!(
                tool.contains(required),
                "OMEGA-DELTA-0137: the delegate contract lost `{required}`."
            );
        }
        assert!(
            tool.contains("report.agent_id.starts_with(\"exo/\")")
                && tool.contains("agent_id: \"exo\".to_owned()")
                && tool.contains("agent_id: \"Omega Agent\".to_owned()"),
            "OMEGA-DELTA-0137: a hosted Exo result no longer names the full \
             Omega → Exo → hosted executor chain."
        );
        for required in [
            "insufficient credits",
            "credit balance",
            "billing quota",
            "quota exceeded",
            "credential_failures_are_not_exhausted_accounts",
        ] {
            assert!(
                tool.contains(required),
                "OMEGA-DELTA-0137: delegate failure classification lost `{required}`."
            );
        }
        assert!(
            !function_body(&tool, "classify_execution_failure")
                .expect("OMEGA-DELTA-0137: delegate failure classifier is gone")
                .contains("error.contains(\"credit\")"),
            "OMEGA-DELTA-0137: a broad credit substring can misclassify \
             credential failures as exhausted accounts."
        );

        let resolver = read_repository_file("crates/agent/src/tools/subagent_executor.rs");
        for required in [
            "requested == \"native\"",
            "requested == \"auto\"",
            "requested.strip_prefix(\"engine:\")",
            "requested.trim() == \"exo\"",
            "substitute a different executor",
        ] {
            assert!(
                resolver.contains(required),
                "OMEGA-DELTA-0137: executor resolution lost `{required}`."
            );
        }
        assert!(
            !resolver.contains("\"khala\""),
            "OMEGA-DELTA-0137: Khala was admitted before its K1–K3 contract."
        );

        let servers = read_repository_file("crates/agent_servers/src/custom.rs");
        assert!(
            servers.contains("pub struct CommandAgentServer")
                && servers.contains("crate::acp::connect("),
            "OMEGA-DELTA-0137: installed lanes can no longer reuse the ordinary \
             ACP transport without synthetic settings or a second home."
        );

        let agent = read_repository_file("crates/agent/src/agent.rs");
        assert!(
            agent.contains("external_subagents: Rc<RefCell<HashMap<")
                && agent.contains("self.external_subagents.borrow().contains_key(&session_id)")
                && agent.contains("external_subagent_thread(&session_id, cx)"),
            "OMEGA-DELTA-0137: external delegate sessions are no longer retained \
             by their parent or their returned address is no longer readable."
        );
    }

    /// OMEGA-DELTA-0138. Slim-agent reliability claims require candidate-bound
    /// journey evidence, a same-task basic-versus-wide comparison, and a
    /// complete watched delta sweep.
    #[test]
    fn slim_agent_claims_are_bound_to_journeys_comparison_and_delta_sweep() {
        let proof = read_repository_file("script/prove-omega-slim-agent");
        for required in [
            "openagents.omega.slim-agent-installed-journey.v1",
            "openagents.omega.slim-agent-harness-journey.v1",
            "openagents.omega.slim-agent-eval-comparison.v1",
            "installed_external_executors",
            "google/gemini-3.6-flash",
            "one integrated source commit",
            "validator checkout HEAD",
            "A fixture or development receipt is not a signed packaged-release claim.",
        ] {
            assert!(
                proof.contains(required),
                "OMEGA-DELTA-0138: the proof protocol lost `{required}`."
            );
        }
        for delta in 133..=138 {
            let delta = format!("OMEGA-DELTA-{delta:04}");
            assert!(
                proof.contains(&delta),
                "OMEGA-DELTA-0138: the integrated sweep no longer requires {delta}."
            );
        }

        let eval = read_repository_file("crates/eval_cli/src/main.rs");
        for required in [
            "profile: EvalProfile",
            "EvalProfile::Basic",
            "EvalProfile::Wide",
            r#""default_profile": "basic""#,
            r#""default_profile": "write""#,
            "cannot alter the closed basic profile",
        ] {
            assert!(
                eval.contains(required),
                "OMEGA-DELTA-0138: eval profile comparison lost `{required}`."
            );
        }

        let harness = read_repository_file("crates/eval_cli/zed_eval/harness_command.py");
        assert!(
            harness.contains("EVAL_CLI_PROFILE=") && harness.contains("\"agent_profile\""),
            "OMEGA-DELTA-0138: zed-eval no longer records or forwards the \
             selected Omega profile."
        );

        let documentation = read_repository_file("docs/src/development/omega-slim-agent-proof.md");
        assert!(
            documentation.contains("Fixture evidence is not packaged evidence")
                && documentation.contains("--agent-profile basic")
                && documentation.contains("--agent-profile wide"),
            "OMEGA-DELTA-0138: the operator protocol no longer states the \
             evidence boundary or the same-task profile comparison."
        );
    }

