    /// OMEGA-DELTA-0157. A mobile Agent-thread command crosses the UI boundary
    /// at most once even when durable completion must be retried.
    #[test]
    fn mobile_agent_commands_persist_admission_before_thread_delivery() {
        let effectd = without_comments(&read_repository_file(
            "crates/omega_effectd/src/sarah_conversation.rs",
        ));
        for required in [
            "Issue31AgentThreadAdmissionState",
            "mark_agent_thread_command_admitted",
            "mark_agent_thread_command_pending",
            "a completion retry must not make the delivered command admissible again",
        ] {
            assert!(
                effectd.contains(required),
                "OMEGA-DELTA-0157: durable mobile-command admission lost `{required}`."
            );
        }

        let host_bridge = without_comments(&read_repository_file(
            "crates/agent_ui/src/omega_host_bridge.rs",
        ));
        let pump = function_body(&host_bridge, "start_issue31_agent_command_pump")
            .expect("OMEGA-DELTA-0157: the mobile Agent command pump is gone");
        let durable_admission = pump
            .find("mark_agent_thread_command_admitted")
            .expect("OMEGA-DELTA-0157: the command is not durably admitted");
        let thread_admission = pump
            .find("admit_issue31_agent_thread_command")
            .expect("OMEGA-DELTA-0157: the Agent-thread boundary is gone");
        assert!(
            durable_admission < thread_admission
                && pump.contains("Issue31AgentThreadAdmissionState::Pending")
                && pump.contains("complete_agent_thread_command"),
            "OMEGA-DELTA-0157: command delivery can precede its durable \
             admission fence or a delivered command can be re-admitted."
        );
    }

    /// OMEGA-DELTA-0159. Automatic hosted sign-in only uses an identity the
    /// owner has already made ready, and every refusal is logged and named.
    #[test]
    fn hosted_sign_in_respects_identity_consent_and_names_every_refusal() {
        let proof = read_repository_file("crates/omega_effectd/src/openagents_nostr_auth.rs");
        let mint = function_body(&proof, "mint_openagents_nostr_session_for_identity")
            .expect("OMEGA-DELTA-0159: the background proof is gone");
        let identity = function_body(&proof, "ready_local_identity")
            .expect("OMEGA-DELTA-0159: the consent-aware identity boundary is gone");
        let account_identity = function_body(&proof, "ready_account_identity")
            .expect("OMEGA-DELTA-0159: active-account identity selection is gone");
        let inspection = account_identity
            .find(".inspect()")
            .expect("OMEGA-DELTA-0159: hosted sign-in stopped inspecting custody");
        // Amended with OMEGA-DELTA-0201: the exact-signing body moved into
        // `sign_nip98_request_once`, and the public `sign_nip98_request`
        // wrapper re-resolves and retries exactly once when the account
        // generation advanced mid-proof.
        let signing = function_body(&proof, "sign_nip98_request_once")
            .expect("OMEGA-DELTA-0159: the signing step is gone");
        let retry_wrapper = function_body(&proof, "sign_nip98_request")
            .expect("OMEGA-DELTA-0159: the retry-once signing wrapper is gone");
        assert!(
            retry_wrapper.contains("STALE_SELECTION_REASON")
                && retry_wrapper.matches("sign_nip98_request_once(").count() >= 2,
            "OMEGA-DELTA-0201: a mid-proof account-generation bump no longer \
             re-resolves and retries once, so one benign race dead-ends the \
             hosted lane again."
        );
        assert!(
            inspection < account_identity.len()
                && mint.contains("ready_account_identity()")
                && mint.contains("sign_nip98_post")
                && signing.contains("SignerBroker::system()")
                && signing.contains(".sign(&route, selection, request)")
                && !identity.contains("provision_unattended")
                && !identity.contains(".create(")
                && !identity.contains(".adopt(")
                && !account_identity.contains("provision_unattended")
                && !account_identity.contains(".create(")
                && !account_identity.contains(".adopt("),
            "OMEGA-DELTA-0159: {} can create, adopt, or replace an identity \
             while performing automatic hosted sign-in.",
            repository_path("crates/omega_effectd/src/openagents_nostr_auth.rs").display()
        );
        assert!(
            mint.contains("log::error!") && mint.contains("HTTP {status}"),
            "OMEGA-DELTA-0159: hosted sign-in stopped logging its failures \
             with the status that explains them."
        );
        let session = read_repository_file("crates/omega_effectd/src/openagents_session.rs");
        let sarah_session = function_body(&session, "prepare_sarah_voice_admission")
            .expect("OMEGA-DELTA-0159: the Sarah admission boundary is gone");
        assert!(
            sarah_session.contains("owner_user_id: None")
                && sarah_session.contains("prepare_nostr_sarah_voice_admission")
                && !sarah_session.contains("self.connect(")
                && !sarah_session.contains("owner_user_id: issued.admission.owner_ref"),
            "OMEGA-DELTA-0159: Sarah persisted the server-returned account mapping \
             in its Nostr-issued bearer credential."
        );

        // Pairing reaches identity custody before hosted sign-in ever runs: a
        // person can click "Pair phone" without sending a message. If only the
        // hosted lane provisions, that click on a fresh install refuses with
        // "custody is not ready" and nothing on screen can make it ready.
        let bridge = read_repository_file("crates/agent_ui/src/omega_host_bridge.rs");
        let pairing = function_body(&bridge, "production_sarah_conversation")
            .expect("OMEGA-DELTA-0159: the pairing conversation constructor is gone");
        assert!(
            pairing.contains("provision_unattended"),
            "OMEGA-DELTA-0159: phone pairing no longer provisions custody, so \
             a fresh install that pairs before it chats is refused."
        );

        let custody = read_repository_file("crates/omega_identity/src/custody.rs");
        let unattended = function_body(&custody, "provision_unattended")
            .expect("OMEGA-DELTA-0159: unattended provisioning is gone");
        assert!(
            unattended.contains("CustodyState::Absent => self.create(receipt_ref)")
                && unattended
                    .contains("CustodyState::Unadopted => self.adopt_custodied(receipt_ref)")
                && unattended.contains("state => Err(CustodyError::CustodyDenied(state))"),
            "OMEGA-DELTA-0159: unattended provisioning no longer refuses every \
             state but `Absent` and `Unadopted`; replacing a `Lost` or \
             `Conflict` identity without the owner is the silent pick \
             omega#110 forbids."
        );

        let provider = read_repository_file(GOOGLE_PROVIDER_PATH);
        assert!(
            !provider.contains("OpenAgents sign-in was not completed")
                && provider.contains("hosted_sign_in_failure_message"),
            "OMEGA-DELTA-0159: {} reports a generic incomplete sign-in again \
             instead of the reason the hosted lane actually refused.",
            repository_path(GOOGLE_PROVIDER_PATH).display()
        );
    }

